// Push gate: decides whether the agent may send a push to a user right now.
// Rules, checked in this order:
//   1. quiet hours (user's local clock, window may cross midnight)
//   2. daily cap (user's local calendar day, not a rolling 24h and not UTC)
// A blocked attempt is not recorded. An allowed attempt is recorded as sent.

const formatters = new Map();

function localParts(date, timeZone) {
  let fmt = formatters.get(timeZone);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat("en-CA", {
      timeZone,
      hourCycle: "h23",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    });
    formatters.set(timeZone, fmt);
  }
  const p = {};
  for (const { type, value } of fmt.formatToParts(date)) p[type] = value;
  return {
    dayKey: `${p.year}-${p.month}-${p.day}`,
    minutes: Number(p.hour) * 60 + Number(p.minute),
  };
}

function parseHHMM(s) {
  const m = typeof s === "string" ? /^([01]\d|2[0-3]):([0-5]\d)$/.exec(s) : null;
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
}

function inQuietHours(minutes, start, end) {
  if (start === end) return false; // empty window: no quiet hours
  if (start < end) return minutes >= start && minutes < end;
  return minutes >= start || minutes < end; // crosses midnight
}

const KEEP_MS = 3 * 24 * 60 * 60 * 1000; // enough to cover any local day (offsets are within +-14h)

export function createPushGate() {
  const sent = new Map(); // user id -> array of epoch ms of pushes allowed

  function attempt(user, now) {
    const t = now instanceof Date ? now.getTime() : NaN;
    if (!user || typeof user.id !== "string" || Number.isNaN(t)) {
      return { allowed: false, reason: "invalid_input" };
    }
    const start = parseHHMM(user.quietStart);
    const end = parseHHMM(user.quietEnd);
    const cap = user.dailyCap;
    if (start === null || end === null || !Number.isInteger(cap) || cap < 0) {
      return { allowed: false, reason: "invalid_user_settings" };
    }

    let local;
    try {
      local = localParts(now, user.timeZone);
    } catch {
      return { allowed: false, reason: "invalid_user_settings" };
    }

    if (inQuietHours(local.minutes, start, end)) {
      return { allowed: false, reason: "quiet_hours" };
    }

    const history = (sent.get(user.id) ?? []).filter((ms) => t - ms < KEEP_MS);
    const today = history.filter(
      (ms) => localParts(new Date(ms), user.timeZone).dayKey === local.dayKey,
    ).length;
    if (today >= cap) {
      sent.set(user.id, history);
      return { allowed: false, reason: "daily_cap_reached" };
    }

    history.push(t);
    sent.set(user.id, history);
    return { allowed: true, reason: null };
  }

  return { attempt };
}

import assert from "node:assert/strict";
import { createPushGate } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-sonnet/work/baseline-g2-3/bot.mjs";

const tokyo = { id: "u1", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const d = (s) => new Date(s);
let g = createPushGate();

// Tokyo = UTC+9. 2026-03-10T01:00Z = 10:00 JST
assert.deepEqual(g.attempt(tokyo, d("2026-03-10T01:00:00Z")), { allowed: true, reason: null });
// 13:30Z = 22:30 JST quiet
assert.equal(g.attempt(tokyo, d("2026-03-10T13:30:00Z")).reason, "quiet_hours");
// 21:59Z = 06:59 JST next day quiet; 22:00Z = 07:00 allowed (end exclusive)
assert.equal(g.attempt(tokyo, d("2026-03-10T21:59:00Z")).reason, "quiet_hours");
assert.equal(g.attempt(tokyo, d("2026-03-10T22:00:00Z")).allowed, true); // new local day (Mar 11)
// cap: Mar 10 JST already 1 (10:00). add 2 more, 4th blocked
assert.equal(g.attempt(tokyo, d("2026-03-10T02:00:00Z")).allowed, true);
assert.equal(g.attempt(tokyo, d("2026-03-10T03:00:00Z")).allowed, true);
assert.equal(g.attempt(tokyo, d("2026-03-10T04:00:00Z")).reason, "daily_cap_reached");
// 14:59Z = 23:59 JST is quiet -> quiet wins; blocked didn't count
// local midnight reset: cap resets at 15:00Z but that's quiet; 22:00Z Mar 11 07:00 -> Mar 11 had 1 so far
assert.equal(g.attempt(tokyo, d("2026-03-10T23:00:00Z")).allowed, true);
assert.equal(g.attempt(tokyo, d("2026-03-11T00:00:00Z")).allowed, true);
assert.equal(g.attempt(tokyo, d("2026-03-11T01:00:00Z")).reason, "daily_cap_reached");

// Daytime window, same-day; and not-crossing
g = createPushGate();
const la = { id: "u2", timeZone: "America/Los_Angeles", quietStart: "12:00", quietEnd: "13:00", dailyCap: 1 };
assert.equal(g.attempt(la, d("2026-07-01T19:30:00Z")).reason, "quiet_hours"); // 12:30 PDT
assert.equal(g.attempt(la, d("2026-07-01T20:00:00Z")).allowed, true);       // 13:00 PDT
assert.equal(g.attempt(la, d("2026-07-01T23:00:00Z")).reason, "daily_cap_reached");
// local day, not UTC: 2026-07-02T06:59Z = 23:59 PDT Jul 1 still capped; 07:00Z = 00:00 Jul 2 allowed
const la2 = { ...la, quietStart: "02:00", quietEnd: "03:00" };
assert.equal(g.attempt(la2, d("2026-07-02T06:59:00Z")).reason, "daily_cap_reached");
assert.equal(g.attempt(la2, d("2026-07-02T07:00:00Z")).allowed, true);

// independence + invalid
const g2 = createPushGate();
assert.equal(g2.attempt(la, d("2026-07-01T20:00:00Z")).allowed, true);
assert.equal(g.attempt({ ...la, timeZone: "Nope/Zone" }, d("2026-07-01T20:00:00Z")).reason, "invalid_user_settings");
assert.equal(g.attempt({ ...la, quietStart: "25:00" }, d("2026-07-01T20:00:00Z")).reason, "invalid_user_settings");
assert.equal(g.attempt(la, new Date(NaN)).reason, "invalid_input");
// DST: Europe/Berlin spring forward 2026-03-29; 00:30Z = 01:30 CET quiet 01:00-03:00
const be = { id: "u3", timeZone: "Europe/Berlin", quietStart: "01:00", quietEnd: "03:00", dailyCap: 5 };
assert.equal(g.attempt(be, d("2026-03-29T00:30:00Z")).reason, "quiet_hours");
assert.equal(g.attempt(be, d("2026-03-29T01:30:00Z")).allowed, true); // 03:30 CEST
console.log("all ok");
